  /**
   * @method
   * @name foxbit#fetchOHLCV
   * @description Fetch historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market.
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Market-Data/operation/MarketsController_findCandlesticks
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any interval =
                     this->safeString(this->timeframes, timeframe, timeframe);
                 ccxt::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"), interval},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("start_time"),
                              this->iso8601(since));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                   if (isTrue(isGreaterThan(limit, 500))) {
                     ::setValue(request, std::string("limit"), 500);
                   }
                 }
                 ccxt::any response =
                     awaitValue(this->v3PublicGetMarketsMarketCandlesticks(
                         this->extend(request, params)));
                 // [
                 //     [
                 //         "1692918000000", // timestamp
                 //         "127772.05150000", // open
                 //         "128467.99980000", // high
                 //         "127750.01000000", // low
                 //         "128353.99990000", // close
                 //         "1692918060000", // close timestamp
                 //         "0.17080431", // base volume
                 //         "21866.35948786", // quote volume
                 //         66, // number of trades
                 //         "0.12073605", // taker buy base volume
                 //         "15466.34096391" // taker buy quote volume
                 //     ]
                 // ]
                 return this->parseOHLCVs(this->toArray(response), market,
                                          interval, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name foxbit#fetchBalance
   * @description Query for balance and get the amount of funds available for
   * trading or funds locked in orders.
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Account/operation/AccountsController_all
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response =
                     awaitValue(this->v3PrivateGetAccounts(params));
                 // {
                 //     "data": [
                 //         {
                 //         "currency_symbol": "btc",
                 //         "balance": "10000.0",
                 //         "balance_available": "9000.0",
                 //         "balance_locked": "1000.0"
                 //         }
                 //     ]
                 // }
                 ccxt::any accounts = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 ccxt::any result = ccxt::dict{
                     {std::string("info"), response},
                 };
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(accounts));
                      postFixIncrement(i)) {
                   ccxt::any account = ::getValue(accounts, i);
                   ccxt::any currencyId = this->safeString(
                       account, std::string("currency_symbol"));
                   ccxt::any currencyCode = this->safeCurrencyCode(currencyId);
                   ccxt::any total =
                       this->safeString(account, std::string("balance"));
                   ccxt::any used =
                       this->safeString(account, std::string("balance_locked"));
                   ccxt::any free = this->safeString(
                       account, std::string("balance_available"));
                   ccxt::any balanceObj = ccxt::dict{
                       {std::string("free"), free},
                       {std::string("used"), used},
                       {std::string("total"), total},
                   };
                   if (isTrue(!isEqual(currencyCode, ccxt::any{}))) {
                     ::setValue(result, currencyCode, balanceObj);
                   }
                 }
                 return this->safeBalance(result);
               })
        .share();
  }

