  /**
   * @method
   * @name foxbit#fetchDepositAddress
   * @description Fetch the deposit address for a currency associated with this
   * account.
   * @see
   * https://docs.foxbit.com.br/rest/v3/#tag/Deposit/operation/DepositsController_depositAddress
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.networkCode] the blockchain network to create a
   * deposit address on
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<ccxt::any>
  fetchDepositAddress(ccxt::any code,
                      ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any currency = this->currency(code);
                        ccxt::any request = ccxt::dict{
                            {std::string("currency_symbol"),
                             ::getValue(currency, std::string("id"))},
                        };
                        ccxt::any networkCodeparamsOmitedVariable =
                            this->handleNetworkCodeAndParams(params);
                        ccxt::any networkCode =
                            ::getValue(networkCodeparamsOmitedVariable, 0);
                        ccxt::any paramsOmited =
                            ::getValue(networkCodeparamsOmitedVariable, 1);
                        if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
                          ::setValue(request, std::string("network_code"),
                                     this->networkCodeToId(networkCode, code));
                        }
                        ccxt::any response =
                            awaitValue(this->v3PrivateGetDepositsAddress(
                                this->extend(request, paramsOmited)));
                        // {
                        //     "currency_symbol": "btc",
                        //     "address": "2N9sS8LgrY19rvcCWDmE1ou1tTVmqk4KQAB",
                        //     "message": "Address was retrieved successfully",
                        //     "destination_tag": "string",
                        //     "network": {
                        //         "name": "Bitcoin Network",
                        //         "code": "btc"
                        //     }
                        // }
                        return this->parseDepositAddress(response, currency);
                      })
        .share();
  }

